package dev.jackteng.encore;

import com.fasterxml.jackson.databind.ObjectMapper;
import dev.jackteng.encore.inventory.*;
import dev.jackteng.encore.inventory.StockReturnService.Command;
import dev.jackteng.encore.orders.*;
import dev.jackteng.encore.orders.OrderModels.*;
import dev.jackteng.encore.orders.PaymentModels.*;
import dev.jackteng.encore.common.ApiErrors.Problem;
import java.time.Duration;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.context.ApplicationContext;
import org.springframework.dao.DataAccessException;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import static org.junit.jupiter.api.Assertions.*;

@SpringBootTest(properties={"ticket.delivery.enabled=false","ticket.admission.enabled=false","ticket.orders.enabled=true",
 "ticket.purchases.enabled=true","ticket.mock-payments.enabled=true","ticket.expiry.enabled=false",
 "ticket.admission.namespace=encore-demo-increment-return-test"})
@TestInstance(TestInstance.Lifecycle.PER_CLASS)
class StockReturnIntegrationTest {
 @Autowired ApplicationContext context; @Autowired StockReturnService returns; @Autowired StockProjectionService projections;
 @Autowired StockSettlementService settlement; @Autowired StockHoldService holds; @Autowired PurchaseService purchases;
 @Autowired OrderService orders; @Autowired PaymentService payments; @Autowired JdbcTemplate db; @Autowired StringRedisTemplate redis;
 @Autowired PlatformTransactionManager transactions; CommitCursorFixture fixtures; Set<String> keys=new HashSet<>();
 record Returned(CommitCursorFixture.Fixture f,UUID order,long revision) {}
 @BeforeAll void setup(){fixtures=new CommitCursorFixture(context);}
 @AfterEach void cleanup(){redis.delete(keys);keys.clear();}
 CommitCursorFixture.Fixture accepted(boolean extra){var f=fixtures.accepted(extra);keys.add(fixtures.ledger.key(f.ticket(),1));keys.add(fixtures.experiment.cursorKey(f.ticket(),1));return f;}
 UUID process(CommitCursorFixture.Fixture f,boolean ack){assertTrue(purchases.process(f.event()));if(ack)assertEquals("COMMITTED",settlement.reconcile(f.intent()).resolution());return db.queryForObject("SELECT order_id FROM stock_hold_decision WHERE intent_id=?",UUID.class,f.intent());}
 Returned returned(){var f=accepted(false);var o=process(f,true);orders.cancel(f.owner(),o,new Cancel(UUID.randomUUID(),1));return new Returned(f,o,3);}
 Command begin(Returned r){var c=returns.begin(UUID.randomUUID(),r.order(),r.revision());keys.add(fixtures.ledger.key(c.ticketId(),c.generation()));return c;}
 void problem(String code,Runnable action){assertEquals(code,assertThrows(Problem.class,action::run).code);}
 int count(Command c,String table){return db.queryForObject("SELECT count(*) FROM "+table+" WHERE request_id=?",Integer.class,c.requestId());}
 void ready(Command c){var result=returns.reconcile(c.requestId());assertEquals("APPLIED",result.state());assertFalse(result.historicalReplay());assertEquals(1,count(c,"stock_return_ack"));assertEquals(2,count(c,"stock_return_audit"));}
 void auditFault(UUID request,String phase){db.execute("ALTER TABLE stock_return_audit ADD CONSTRAINT return_fault CHECK(request_id<>'"+request+"'::uuid OR phase<>'"+phase+"') NOT VALID");}
 void unfault(){db.execute("ALTER TABLE stock_return_audit DROP CONSTRAINT return_fault");}

 @Test void cancelledCommitHandoffsFullPgSnapshotToNewSpendableEpoch(){var r=returned();var original=redis.opsForHash().entries(fixtures.ledger.key(r.f().ticket(),1));var c=begin(r);assertEquals(1,c.sourceGeneration());assertEquals(2,c.generation());assertEquals(4,c.available());assertEquals("CLOSED",projections.inspect(c.ticketId()).state());assertFalse(redis.hasKey(fixtures.ledger.key(c.ticketId(),2)));ready(c);var i=holds.prepare(r.f().owner(),new Place(UUID.randomUUID(),c.ticketId(),1,1,1200));assertEquals(2,i.generation());assertEquals("HELD",holds.apply(i.id()).state());assertEquals(3,fixtures.ledger.snapshot(c.ticketId(),2).snapshot().available());assertEquals(original,redis.opsForHash().entries(fixtures.ledger.key(c.ticketId(),1)));assertEquals("COMMIT",db.queryForObject("SELECT target FROM stock_hold_decision WHERE intent_id=?",String.class,r.f().intent()));assertTrue(returns.reconcile(c.requestId()).historicalReplay());}
 @Test void fullSnapshotKeepsOtherSoldStockInsteadOfAddingReturnQuantityToCapacity(){var f=accepted(false);var second=holds.prepare(f.owner(),new Place(UUID.randomUUID(),f.ticket(),1,1,1200));assertEquals("HELD",holds.apply(second.id()).state());var p=purchases.acceptHold(f.owner(),second.id());var event=db.queryForObject("SELECT id FROM purchase_outbox WHERE purchase_id=?",UUID.class,p.id());var firstOrder=process(f,true);assertTrue(purchases.process(event));settlement.reconcile(second.id());var secondOrder=db.queryForObject("SELECT order_id FROM stock_hold_decision WHERE intent_id=?",UUID.class,second.id());var pay=payments.start(f.owner(),secondOrder,new Pay(UUID.randomUUID(),1,1200,"SUCCESS"));payments.reconcile(f.owner(),secondOrder,pay.payment().id(),new Reconcile(UUID.randomUUID()));orders.cancel(f.owner(),firstOrder,new Cancel(UUID.randomUUID(),1));var c=begin(new Returned(f,firstOrder,5));assertEquals(3,c.available());ready(c);assertEquals(3,fixtures.ledger.snapshot(c.ticketId(),2).snapshot().available());assertEquals(1,db.queryForObject("SELECT sold FROM ticket_type WHERE id=?",Integer.class,c.ticketId()));}
 @Test void oldCommitReturnedAfterIntermediateRebuildUsesReleaseGeneration(){var f=accepted(false);var order=process(f,true);var middle=projections.begin(f.ticket(),UUID.randomUUID(),2);keys.add(fixtures.ledger.key(f.ticket(),2));assertEquals("READY",projections.complete(middle.requestId()).state());orders.cancel(f.owner(),order,new Cancel(UUID.randomUUID(),1));var c=begin(new Returned(f,order,3));assertEquals(2,c.sourceGeneration());assertEquals(3,c.generation());ready(c);assertEquals(4,fixtures.ledger.snapshot(c.ticketId(),3).snapshot().available());assertTrue(redis.opsForHash().get(fixtures.ledger.key(c.ticketId(),1),"r:"+f.intent()).toString().contains("COMMITTED"));}
 @Test void expiredCommitUsesSameSeparateReturnOrigin(){var f=accepted(false);var order=process(f,true);db.update("WITH stamp AS MATERIALIZED(SELECT clock_timestamp() clock) UPDATE ticket_order SET created_at=clock-interval '11 minutes',expires_at=clock-interval '1 minute' FROM stamp WHERE id=?",order);assertTrue(orders.expire(order));assertFalse(orders.expire(order));var c=begin(new Returned(f,order,3));ready(c);assertEquals(4,fixtures.ledger.snapshot(c.ticketId(),2).snapshot().available());assertTrue(redis.opsForHash().get(fixtures.ledger.key(c.ticketId(),1),"r:"+f.intent()).toString().contains("COMMITTED"));}
 @Test void sixConcurrentOriginalBeginsAllocateOnlyOneCommandGenerationAndAudit()throws Exception{var r=returned();var request=UUID.randomUUID();try(var pool=Executors.newFixedThreadPool(6)){var jobs=new ArrayList<Callable<Command>>();for(int n=0;n<6;n++)jobs.add(()->returns.begin(request,r.order(),3));for(var result:pool.invokeAll(jobs)){var c=result.get();assertEquals(2,c.generation());keys.add(fixtures.ledger.key(c.ticketId(),2));}}assertEquals(2,projections.inspect(r.f().ticket()).generation());assertEquals(1,db.queryForObject("SELECT count(*) FROM stock_return_command WHERE order_id=?",Integer.class,r.order()));}
 @Test void sixConcurrentCompletionsCommitOneAckAndHistoricalReplays()throws Exception{var c=begin(returned());try(var pool=Executors.newFixedThreadPool(6)){var jobs=new ArrayList<Callable<StockReturnService.Outcome>>();for(int n=0;n<6;n++)jobs.add(()->returns.reconcile(c.requestId()));int applied=0;for(var result:pool.invokeAll(jobs)){var out=result.get();assertEquals("APPLIED",out.state());if(!out.historicalReplay())applied++;}assertEquals(1,applied);}assertEquals(1,count(c,"stock_return_ack"));assertEquals(2,count(c,"stock_return_audit"));}
 @Test void registeredAuditFailureRollsBackFreshGenerationAndRebuildTogether(){var r=returned();var request=UUID.randomUUID();auditFault(request,"REGISTERED");try{assertThrows(DataAccessException.class,()->returns.begin(request,r.order(),3));}finally{unfault();}assertEquals(1,projections.inspect(r.f().ticket()).generation());assertEquals("DIRTY",projections.inspect(r.f().ticket()).state());assertEquals(0,db.queryForObject("SELECT count(*) FROM stock_rebuild_command WHERE request_id=?",Integer.class,request));assertEquals("CANCELLED",orders.detail(r.f().owner(),r.order()).status());var c=returns.begin(request,r.order(),3);keys.add(fixtures.ledger.key(c.ticketId(),2));ready(c);}
 @Test void readyAuditRollbackAfterRedisOpenPreservesClosedPgAndOriginalReplay(){var c=begin(returned());auditFault(c.requestId(),"APPLIED");try{assertThrows(DataAccessException.class,()->returns.reconcile(c.requestId()));}finally{unfault();}assertEquals("CLOSED",projections.inspect(c.ticketId()).state());assertEquals(RedisTicketLedger.Phase.OPEN,fixtures.ledger.snapshot(c.ticketId(),2).snapshot().phase());assertEquals(0,count(c,"stock_return_ack"));assertEquals(1,count(c,"stock_return_audit"));ready(c);assertEquals(2,projections.inspect(c.ticketId()).generation());}
 @Test void unresolvedActiveOrProcessingIntentBlocksHandoff(){for(boolean processing:List.of(false,true)){var f=accepted(true);if(processing){var identity=db.queryForMap("SELECT customer_id,session_version,session_hash FROM stock_hold_intent WHERE id=?",f.extraIntent());var owner=new dev.jackteng.encore.customer.CustomerService.Principal((UUID)identity.get("customer_id"),"",((Number)identity.get("session_version")).longValue(),(String)identity.get("session_hash"));assertEquals("PROCESSING",purchases.acceptHold(owner,f.extraIntent()).status());}var order=process(f,true);orders.cancel(f.owner(),order,new Cancel(UUID.randomUUID(),1));problem("ACTIVE_STOCK_INTENTS",()->returns.begin(UUID.randomUUID(),order,3));assertEquals(1,projections.inspect(f.ticket()).generation());}}
 @Test void originalCommitWithoutCommittedAckCannotAuthorizeReturn(){var f=accepted(false);var order=process(f,false);orders.cancel(f.owner(),order,new Cancel(UUID.randomUUID(),1));problem("RETURN_COMMIT_NOT_ACKNOWLEDGED",()->returns.begin(UUID.randomUUID(),order,3));assertEquals(1,projections.inspect(f.ticket()).generation());}
 @Test void keyMissingAckCannotAuthorizeReturn(){var f=accepted(false);var order=process(f,false);redis.delete(fixtures.ledger.key(f.ticket(),1));assertEquals("KEY_MISSING",settlement.reconcile(f.intent()).resolution());orders.cancel(f.owner(),order,new Cancel(UUID.randomUUID(),1));problem("RETURN_COMMIT_NOT_ACKNOWLEDGED",()->returns.begin(UUID.randomUUID(),order,3));}
 @Test void synchronousReturnCannotPretendToBeAcceptedCommit(){var f=accepted(false);var o=orders.place(f.owner(),new Place(UUID.randomUUID(),f.ticket(),1,1,1200));orders.cancel(f.owner(),o.id(),new Cancel(UUID.randomUUID(),1));problem("RETURN_ORIGIN_REQUIRED",()->returns.begin(UUID.randomUUID(),o.id(),3));}
 @Test void pendingOrPaidOrderDoesNotSupplyReleaseOrigin(){for(boolean paid:List.of(false,true)){var f=accepted(false);var order=process(f,true);if(paid){var o=payments.start(f.owner(),order,new Pay(UUID.randomUUID(),1,1200,"SUCCESS"));payments.reconcile(f.owner(),order,o.payment().id(),new Reconcile(UUID.randomUUID()));}problem("RETURN_ORIGIN_REQUIRED",()->returns.begin(UUID.randomUUID(),order,paid?3:2));}}
 @Test void changedBodyOrNewUuidCannotAdoptOriginalReturn(){var r=returned();var c=begin(r);assertEquals(c,returns.begin(c.requestId(),r.order(),3));problem("RETURN_COMMAND_CONFLICT",()->returns.begin(c.requestId(),r.order(),2));problem("RETURN_COMMAND_CONFLICT",()->returns.begin(UUID.randomUUID(),r.order(),3));var other=returned();problem("RETURN_COMMAND_CONFLICT",()->returns.begin(c.requestId(),other.order(),3));}
 @Test void reusedOrdinaryRebuildUuidCannotBecomeReturnCommand(){var r=returned();var b=projections.begin(r.f().ticket(),UUID.randomUUID(),3);keys.add(fixtures.ledger.key(b.ticketId(),b.generation()));problem("RETURN_COMMAND_CONFLICT",()->returns.begin(b.requestId(),r.order(),3));}
 @Test void returnAlreadyIncludedInLaterGenerationIsNotCreditedAgain(){var r=returned();var b=projections.begin(r.f().ticket(),UUID.randomUUID(),3);keys.add(fixtures.ledger.key(b.ticketId(),b.generation()));projections.complete(b.requestId());problem("RETURN_ALREADY_INCLUDED",()->returns.begin(UUID.randomUUID(),r.order(),3));assertEquals(2,projections.inspect(r.f().ticket()).generation());}
 @Test void newerRevisionBeforeBeginDoesNotAllocateOrChangeOriginalEvent(){var r=returned();orders.place(r.f().owner(),new Place(UUID.randomUUID(),r.f().ticket(),1,1,1200));problem("STOCK_CHANGED",()->returns.begin(UUID.randomUUID(),r.order(),3));assertEquals(1,projections.inspect(r.f().ticket()).generation());}
 @Test void newerRevisionBetweenPhasesFencesOriginalSnapshot(){var r=returned();var c=begin(r);orders.place(r.f().owner(),new Place(UUID.randomUUID(),r.f().ticket(),1,1,1200));problem("STOCK_CHANGED",()->returns.reconcile(c.requestId()));assertFalse(redis.hasKey(fixtures.ledger.key(c.ticketId(),2)));assertEquals(0,count(c,"stock_return_ack"));assertEquals(c,returns.begin(c.requestId(),r.order(),3));}
 @Test void newerGenerationFencesOriginalUncompletedHandoff(){var c=begin(returned());var b=projections.begin(c.ticketId(),UUID.randomUUID(),3);keys.add(fixtures.ledger.key(b.ticketId(),b.generation()));problem("GENERATION_FENCED",()->returns.reconcile(c.requestId()));assertEquals(0,count(c,"stock_return_ack"));}
 @Test void historicalAckDoesNotRecreateLostKeyOrCertifyCurrentReady(){var r=returned();var c=begin(r);ready(c);redis.delete(fixtures.ledger.key(c.ticketId(),2));orders.place(r.f().owner(),new Place(UUID.randomUUID(),c.ticketId(),1,1,1200));assertEquals("DIRTY",projections.inspect(c.ticketId()).state());assertTrue(returns.reconcile(c.requestId()).historicalReplay());assertFalse(redis.hasKey(fixtures.ledger.key(c.ticketId(),2)));assertEquals(2,count(c,"stock_return_audit"));}
 @Test void wrongTypeTtlAndFrozenNewKeyAreNotOverwritten(){for(int mode=0;mode<3;mode++){var c=begin(returned());String key=fixtures.ledger.key(c.ticketId(),2);if(mode==0)redis.opsForValue().set(key,"wrong");if(mode==1){fixtures.ledger.initialize(c.ticketId(),2,4,4096);redis.expire(key,Duration.ofMinutes(1));}if(mode==2){fixtures.ledger.initialize(c.ticketId(),2,4,4096);fixtures.ledger.close(c.ticketId(),2);}var before=mode==0?redis.opsForValue().get(key):redis.opsForHash().entries(key);assertEquals("PENDING",returns.reconcile(c.requestId()).state());assertEquals(before,mode==0?redis.opsForValue().get(key):redis.opsForHash().entries(key));assertEquals(0,count(c,"stock_return_ack"));}}
 @Test void ackAndCommandNeedExactOriginalDomainEvidence(){var c=begin(returned());assertThrows(DataAccessException.class,()->db.update("INSERT INTO stock_return_ack(request_id) VALUES(?)",c.requestId()));assertThrows(DataAccessException.class,()->db.update("INSERT INTO stock_return_command(request_id,ticket_id,order_id,intent_id,release_revision,source_generation,generation,available) VALUES(?,?,?,?,?,?,?,?)",UUID.randomUUID(),c.ticketId(),c.orderId(),c.intentId(),3,1,2,99));}
 @Test void commandAckAndPhaseAuditAreImmutable(){var c=begin(returned());ready(c);for(String table:List.of("stock_return_command","stock_return_ack","stock_return_audit")){assertThrows(DataAccessException.class,()->db.update("DELETE FROM "+table+" WHERE request_id=?",c.requestId()));assertThrows(DataAccessException.class,()->db.update("UPDATE "+table+" SET request_id=request_id WHERE request_id=?",c.requestId()));}}
 @Test void outerTransactionCannotMakeEitherIndependentPhaseAppearCommitted(){var r=returned();new TransactionTemplate(transactions).executeWithoutResult(s->assertThrows(IllegalStateException.class,()->returns.begin(UUID.randomUUID(),r.order(),3)));var c=begin(r);new TransactionTemplate(transactions).executeWithoutResult(s->assertThrows(IllegalStateException.class,()->returns.reconcile(c.requestId())));assertEquals(0,count(c,"stock_return_ack"));}
}
